// Memoria de esta pestaña. Nunca se guarda en localStorage ni sessionStorage.
const TTL_MS = 5 * 60 * 1000
let generation = 0
let entry: { token: string; expiresAt: number; promise: Promise<unknown> } | undefined

export function clearCatalogLookupCache() {
  generation++
  entry = undefined
}

export function readCatalogLookupCache<T>(token: string, load: () => Promise<T>): Promise<T> {
  if (entry?.token === token && entry.expiresAt > Date.now())
    return entry.promise as Promise<T>
  clearCatalogLookupCache()
  const version = generation
  const promise = Promise.resolve().then(load).then(value => {
    if (version !== generation) throw new DOMException('La consulta fue invalidada.', 'AbortError')
    if (entry?.promise === promise) entry.expiresAt = Date.now() + TTL_MS
    return value
  }).catch(error => {
    if (entry?.promise === promise) entry = undefined
    throw error
  })
  entry = { token, expiresAt: Infinity, promise }
  return promise
}

import { listCategories } from '../../categories/api/categoriesApi.ts'
import { listBrands } from '../../brands/api/brandsApi.ts'
import { readCatalogLookupCache } from '../../../shared/cache/catalogLookupCache.ts'

export interface CatalogCategoryOption { idCategoria: number; nombre: string; estado: boolean }
export interface CatalogBrandOption { idMarca: number; nombre: string; idCategoria: number; estado: boolean }
export interface CatalogLookups { categories: CatalogCategoryOption[]; brands: CatalogBrandOption[] }

export function loadCatalogLookups(token: string): Promise<CatalogLookups> {
  return readCatalogLookupCache(token, async () => {
    const [categories, brands] = await Promise.all([
      listCategories(token, undefined, true),
      listBrands(token, undefined, true),
    ])
    return {
      categories: categories.map(({ idCategoria, nombre, estado }) => ({ idCategoria, nombre, estado })),
      brands: brands.map(({ idMarca, nombre, idCategoria, estado }) => ({ idMarca, nombre, idCategoria, estado })),
    }
  })
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { clearCatalogLookupCache, readCatalogLookupCache } from '../src/shared/cache/catalogLookupCache.ts'

test('comparte consultas simultáneas y resultados de la sesión', async () => {
  clearCatalogLookupCache()
  let calls = 0
  const load = async () => { calls++; return ['Bebidas'] }
  const first = readCatalogLookupCache('a', load)
  const second = readCatalogLookupCache('a', load)
  assert.equal(first, second)
  assert.deepEqual(await first, ['Bebidas'])
  await readCatalogLookupCache('a', load)
  assert.equal(calls, 1)
})

test('cambio de sesión e invalidación descartan respuestas pendientes', async () => {
  clearCatalogLookupCache()
  let finish!: (value: string[]) => void
  const old = readCatalogLookupCache('a', () => new Promise<string[]>(resolve => { finish = resolve }))
  await Promise.resolve()
  const rejected = assert.rejects(old, { name: 'AbortError' })
  assert.deepEqual(await readCatalogLookupCache('b', async () => ['Nueva sesión']), ['Nueva sesión'])
  finish(['Anterior'])
  await rejected
  clearCatalogLookupCache()
  assert.deepEqual(await readCatalogLookupCache('b', async () => ['Actualizado']), ['Actualizado'])
})

test('los fallos no quedan cacheados', async () => {
  clearCatalogLookupCache()
  await assert.rejects(readCatalogLookupCache('a', async () => { throw new Error('Sin conexión') }))
  assert.equal(await readCatalogLookupCache('a', async () => 'Reintento'), 'Reintento')
})

test('renueva el listado después de cinco minutos', async () => {
  clearCatalogLookupCache()
  const realNow = Date.now
  let now = 1000
  Date.now = () => now
  try {
    assert.equal(await readCatalogLookupCache('a', async () => 'Antes'), 'Antes')
    now += 300001
    assert.equal(await readCatalogLookupCache('a', async () => 'Después'), 'Después')
  } finally { Date.now = realNow; clearCatalogLookupCache() }
})
